<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account moderation - Finobe</title><style>body{font:14px/1.6 Arial,sans-serif;background:#eee;color:#333;margin:0}.notice{max-width:650px;margin:60px auto;background:#fff;border:1px solid #ccc;padding:30px}h1{font-size:24px;font-weight:normal}blockquote{background:#f6f6ee;border-left:3px solid #b33;padding:15px;margin:15px 0}button{padding:8px 15px;cursor:pointer}small{color:#777}</style></head><body><main class="notice"><a href="/">Finobe</a><h1>{{ $isWarning ? 'Account warning' : 'Account suspended' }}</h1><p>Your account has been reviewed by a moderator.</p><blockquote>{{ $record->reason }}</blockquote><p><small>Reviewed {{ $record->date }}@if(!$isWarning) · {{ $record->expire ? 'Expires '.$record->expire : 'Permanent suspension' }}@endif</small></p>@if($isWarning)<form method="post" action="/moderation/acknowledge">@csrf<label><input type="checkbox" name="acknowledged" value="1" required> I have read this moderation message.</label><p><button type="submit">Reactivate my account</button></p></form>@else<p>You can contact the site's staff if you believe this decision was mistaken.</p>@endif<form method="post" action="/logout" style="display:inline">@csrf<button type="submit" style="padding:8px 15px;cursor:pointer">Log out</button></form></main></body></html>
